func (d DeskDraft) foundryMutation(create bool) (foundryquery.Mutation[Desk], error) {
	if create && !d.fieldID.IsSet() {
		id, err := model.NewID[Desk]()
		if err != nil {
			return foundryquery.Mutation[Desk]{}, err
		}
		d = d.SetID(id)
	}
	var assignments []foundryquery.Assignment[Desk]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Desk]("office_desks", "id", codec.ID[Desk](), v))
	}
	if v, set := d.fieldOfficeID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Desk]("office_desks", "office_id", codec.ID[Office](), v))
	}
	if v, set := d.fieldLabel.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Desk]("office_desks", "label", codec.String[string](), v))
	}
	return foundryquery.Change(assignments...), nil
}

