// After returns the persisted model after the operation, or absence for physical deletion. Soft deletion retains its stored result.
func (c DeskChanges) After() foundryvalue.Optional[Desk] { return c.after }

// Fields returns model-specific field changes by value.
func (c DeskChanges) Fields() DeskFieldChanges { return c.fields }

// Assigned reports whether any persisted field is assigned.
